import logging

import attr

from yaml import load, FullLoader
from typing import Optional, Union, Sequence, List

from ..airscale import Airscale, CapacityUnit
from ..radio import RU
from .networkaddress import NetworkAddress
from ..cloud_hosting import CloudDeployment
from ..connection_details import SshServiceDetails, HttpConnectionDetails
from ..lab_infrastructure import PxeServer

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


@attr.s(cmp=False)
class FHGW(object):
    """
    :param str user_config_path: path to yaml_file with config for FHGW. The content of the file
                                 will be available as dict as `user_config` property
    :param Optional[List[RU]] rus: List of objects of RU (Radio Unit) classes (or subclasses)
    :param Optional[PxeServer] pxe_server: PxeServer class instance object
    :param Optional[int] fhgw_id: fronthaul gateway identifier used to uniquely identify the gateway in the network.
                                  Default value: 1. Valid Input Range: 1-68719476735
    :param Optional[str] fhgw_name: fronthaul gateway name used for uniquely identifying the gateway in the network
                                    with user-friendly name. Default value: FHGW-1.
                                    Valid input: 1-80 characters matching regex [A-Z,a-z,0-9,-]
    :param Optional[SshServiceDetails] default_ssh_connection_details: SSH parameters for connection to FHGW
    """
    user_config_path = attr.ib(type=str)
    rus = attr.ib(default=None, type=Optional[Sequence[RU]])
    pxe_server = attr.ib(default=None, type=Optional[PxeServer])
    fhgw_id = attr.ib(default=1, type=Optional[int])
    fhgw_name = attr.ib(default="FHGW-1", type=Optional[str],
                        validator=attr.validators.matches_re("^[A-Z,a-z,0-9,-]{1,80}$"))
    default_ssh_connection_details = attr.ib(default=None, type=Optional[SshServiceDetails])

    @fhgw_id.validator
    def _check_fhgw_id(self, attribute, value):
        max_range = 2 ** 36
        if not 1 <= value < max_range:
            raise ValueError("{attrib_name} should be in range 1-{num}. Actual value: {val}"
                             .format(attrib_name=attribute.name, num=max_range - 1, val=value))

    @property
    def user_config(self):
        with open(self.user_config_path) as f:
            return load(f.read(), Loader=FullLoader)

    def __taf_contract_ssh__(self):
        if self.default_ssh_connection_details is None:
            raise ValueError(
                f"SSH information is not set in this configuration object "
                f"({self.__class__!r})"
            )
        return self.default_ssh_connection_details.__taf_contract_ssh__()


@attr.s(cmp=False)
class RANNIC(object):
    """
    :param Optional[str] serial_number: serial number of the rannic L123456789012
    :param Optional[str] product_code: full product code of the rannic e.g. 11111.X12
    :param Optional[List[RU]] rus: List of objects of RU (Radio Unit) classes (or subclasses)
    """
    serial_number = attr.ib(default=None, type=Optional[str])
    product_code = attr.ib(default=None, type=Optional[str])
    rus = attr.ib(default=None, type=Sequence[RU])


@attr.s(cmp=False)
class Endpoint(object):
    """
    :param Union[CapacityUnit, RU] unit: unit to which Endpoint is connected
    :param Optional[str] label: for example SFP or QSFP
    :param Optional[int] port_id: id of the port
    """
    unit = attr.ib(type=Union[CapacityUnit, RU, FHGW, RANNIC])
    label = attr.ib(default=None, type=Optional[str])
    port_id = attr.ib(default=None, type=Optional[int])


@attr.s(cmp=False)
class Cablink(object):
    """
    :param Endpoint source: Endpoint class instance object
    :param Endpoint target: Endpoint class instance object
    """
    source = attr.ib(type=Endpoint)
    target = attr.ib(type=Endpoint)


@attr.s(cmp=False)
class DU(object):
    """
    :param Airscale airscale: Airscale class instance object
    :param Optional[List[RU]] rus: List of objects of RU (Radio Unit) classes (or subclasses)
    :param Optional[str] oam_ip: oam ip address (MPLANE IP) for DU
    :param Optional[str] f1_m_ip_addr: ip addr for f1-m or NetworkAddress instance
    :param Optional[str] f1_c_ip_addr: ip addr for f1-c or NetworkAddress instance
    :param Optional[str] f1_u_ip_addr: ip addr for f1-u or NetworkAddress instance
    :param Optional[str] f1_m_cu: Routing information for f1-m-CU
    :param Optional[str] f1_c_cu: Routing information for f1-c-CU
    :param Optional[str] f1_u_cu: Routing information for f1-u-CU
    :param Optional[List[Cablink]] cablinks: List of objects of Cablink classes
    :param int instance_id: (optional) Instance Identifier of the MRBTS object. Defaults to None.
    :param int global_bts_id: (optional) Instance identifier of the NRBTS object.
        It is also used as a telecom parameter of the 3GPP Global gNB ID. Defaults to None.
    """
    airscale = attr.ib(type=Airscale)
    rus = attr.ib(default=None, type=Optional[Sequence[RU]])
    oam_ip = attr.ib(default=None, type=Optional[NetworkAddress])
    f1_m_ip_addr = attr.ib(default=None, type=Optional[Union[str, NetworkAddress]])
    f1_c_ip_addr = attr.ib(default=None, type=Optional[Union[str, NetworkAddress]])
    f1_u_ip_addr = attr.ib(default=None, type=Optional[Union[str, NetworkAddress]])
    f1_m_cu = attr.ib(default=None, type=Optional[NetworkAddress])
    f1_c_cu = attr.ib(default=None, type=Optional[NetworkAddress])
    f1_u_cu = attr.ib(default=None, type=Optional[NetworkAddress])
    cablinks = attr.ib(default=None, type=Optional[List[Cablink]])
    instance_id = attr.ib(default=None, type=Optional[int])
    global_bts_id = attr.ib(default=None, type=Optional[int])


@attr.s(cmp=False)
class VDU(object):
    """
    :param CloudDeployment cloud_deployment: CloudDeployment class instance object
    :param HttpConnectionDetails oam_http_connection_details:
    :param Optional[List[FHGW]] fhgws: list of fronthaul gateway objects- FHGW class instance objects
    :param Union[Optional[str], Optional[NetworkAddress]] f1_m_ip_addr:
    :param Union[Optional[str], Optional[NetworkAddress]] f1_c_ip_addr:
    :param Union[Optional[str], Optional[NetworkAddress]] f1_u_ip_addr:
    :param int instance_id: (optional) Instance Identifier of the MRBTS object. Defaults to None.
    :param int global_bts_id: (optional) Instance identifier of the NRBTS object.
        It is also used as a telecom parameter of the 3GPP Global gNB ID. Defaults to None.
    :param Optional[List[int]] fhuc_vlans: list of fhuc vlans
    :param Optional[List[Cablink]] cablinks: Cable connections between hw entities e.g. between rannic and fhgw
    :param Optional[List[RU]] rus: List of objects of RU (Radio Unit) classes (or subclasses)
    :param Optional[List[RANNIC]] rannics: List of RANNIC's available

    """
    cloud_deployment = attr.ib(type=CloudDeployment)
    oam_http_connection_details = attr.ib(type=HttpConnectionDetails)
    fhgws = attr.ib(default=None, type=Optional[Sequence[FHGW]])
    f1_m_ip_addr = attr.ib(default=None, type=Optional[Union[str, NetworkAddress]])
    f1_c_ip_addr = attr.ib(default=None, type=Optional[Union[str, NetworkAddress]])
    f1_u_ip_addr = attr.ib(default=None, type=Optional[Union[str, NetworkAddress]])
    instance_id = attr.ib(default=None, type=Optional[int])
    global_bts_id = attr.ib(default=None, type=Optional[int])
    fhuc_vlans = attr.ib(default=None, type=Optional[List[int]])
    cablinks = attr.ib(default=None, type=Optional[List[Cablink]])
    rus = attr.ib(default=None, type=Optional[Sequence[RU]])
    rannics = attr.ib(default=None, type=Optional[Sequence[RANNIC]])

    @fhuc_vlans.validator
    def _check_fhuc_vlans(self, attribute, values):
        if not values:
            return

        max_value = 4094
        for value in values:
            if not 1 <= value <= max_value:
                raise ValueError("{val} in the {attrib_name} list is not in the correct range 1-{num}."
                                 .format(val=value, attrib_name=attribute.name, num=max_value))

    def __attrs_post_init__(self):
        if self.rus:
            logger.warning(
                "'.rus' attribute for vDU is deprecated, please check for RU presence "
                "in FHGW or RANNIC objects in '.fhgws' and '.rannics'"
            )
